package com.fasterxml.jackson.databind.util;

import com.fasterxml.jackson.core.io.NumberInput;
import java.io.*;
import java.lang.reflect.Method;
import java.math.*;
import java.text.DateFormat;
import java.text.FieldPosition;
import java.text.ParseException;
import java.text.ParsePosition;
import java.text.SimpleDateFormat;
import java.util.*;
import java.util.Date;
import java.util.Locale;
import java.util.TimeZone;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;

/**
 * Unit tests for StdDateFormat._clearFormats().
 * Since _clearFormats is protected, we use reflection to access it.
 */
public class StdDateFormat__clearFormats_TriageGen0Test {

    @Test
    public void test_clearFormats_clearsInternalFormatters() throws Exception {
        // Arrange
        StdDateFormat dateFormat = new StdDateFormat();

        // We need to trigger the creation of internal formats to verify they are cleared.
        // Using parse/format or static factory methods usually populates these fields.
        // Since we cannot see the private fields directly, we verify the behavior 
        // by ensuring that subsequent operations result in a "fresh" state.

        // Trigger internal format initialization by parsing/formatting
        Date now = new Date();
        dateFormat.format(now, new StringBuffer());
        dateFormat.parse("2023-10-27T10:00:00Z");
        dateFormat.parse("Fri, 27 Oct 2023 10:00:00 GMT");

        // Act: Access the protected method via reflection
        Method clearFormatsMethod = StdDateFormat.class.getDeclaredMethod("_clearFormats");
        clearFormatsMethod.setAccessible(true);
        clearFormatsMethod.invoke(dateFormat);

        // Assert: 
        // After clearing, the object should still be functional (it will re-initialize formats on next use).
        // We verify that the object state is consistent and doesn't throw exceptions.
        String formatted = dateFormat.format(now, new StringBuffer());
        assertNotNull(formatted);

        Date parsed = dateFormat.parse("2023-10-27T10:00:00Z");
        assertNotNull(parsed);
    }

    @Test
    public void test_clearFormats_multipleCalls() throws Exception {
        // Arrange
        StdDateFormat dateFormat = new StdDateFormat(TimeZone.getTimeZone("UTC"), Locale.US);
        Method clearFormatsMethod = StdDateFormat.class.getDeclaredMethod("_clearFormats");
        clearFormatsMethod.setAccessible(true);

        // Act & Assert: Ensure calling it multiple times doesn't throw NullPointerException or errors
        clearFormatsMethod.invoke(dateFormat);
        clearFormatsMethod.invoke(dateFormat);
        clearFormatsMethod.invoke(dateFormat);

        // Verify functionality remains intact
        Date now = new Date();
        assertNotNull(dateFormat.format(now, new StringBuffer()));
    }

    @Test
    public void test_clearFormats_withDifferentLocales() throws Exception {
        // Arrange
        StdDateFormat dateFormat = new StdDateFormat(TimeZone.getDefault(), Locale.FRANCE);
        Method clearFormatsMethod = StdDateFormat.class.getDeclaredMethod("_clearFormats");
        clearFormatsMethod.setAccessible(true);

        // Act
        clearFormatsMethod.invoke(dateFormat);

        // Assert
        // Ensure the object is still usable after clearing
        assertNotNull(dateFormat.toString());
        assertNotNull(dateFormat.clone());
    }
}
